exercise.solution:
import numpy as np

def build_index(records):
    if not records:
        raise ValueError("Corpus must be nonempty")
    ids=[]
    vectors=[]
    seen=set()
    dimension=None
    for record in records:
        identifier=record.get("id") if isinstance(record,dict) else None
        if not isinstance(identifier,str) or not identifier.strip() or identifier in seen:
            raise ValueError("IDs must be unique nonblank strings")
        try:
            vector=np.asarray(record.get("embedding"),dtype=float)
        except (TypeError,ValueError) as error:
            raise ValueError("Invalid embedding") from error
        if vector.ndim!=1 or vector.size==0 or not np.all(np.isfinite(vector)) or np.linalg.norm(vector)==0:
            raise ValueError("Embedding must be a finite nonzero vector")
        if dimension is None:
            dimension=vector.size
        if vector.size!=dimension:
            raise ValueError("Embedding dimensions must match")
        seen.add(identifier)
        ids.append(identifier)
        vectors.append(vector)
    return ids,np.stack(vectors)

